import base64, hashlib
from itertools import product

ct_b64 = 'h0Jrzf8acHaDI8YrKhVJcQ=='
ct = base64.b64decode(ct_b64)
print('ciphertext len:', len(ct), 'bytes')
print('hex:', ct.hex())

keys = ['uih', 'vietminh\$123', 'uih.com', 'vietminh']
# try passwords that might have been remembered - we don't know plaintext
# We'll encrypt common passwords and see if match, AND try decrypt with AES

try:
    from Crypto.Cipher import AES, DES, DES3
    from Crypto.Util.Padding import pad, unpad
except ImportError:
    import subprocess, sys
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', 'pycryptodome', '-q'])
    from Crypto.Cipher import AES, DES, DES3
    from Crypto.Util.Padding import pad, unpad

def key_md5(s):
    return hashlib.md5(s.encode('utf-8')).digest()

def key_md5_unicode(s):
    return hashlib.md5(s.encode('utf-16-le')).digest()

def key_sha256_16(s):
    return hashlib.sha256(s.encode('utf-8')).digest()[:16]

def key_pad16(s):
    b = s.encode('utf-8')
    return (b + b'\0'*16)[:16]

def key_pad24(s):
    b = s.encode('utf-8')
    return (b + b'\0'*24)[:24]

def key_repeat(s, n):
    b = (s.encode('utf-8') * ((n//len(s.encode('utf-8')))+1))[:n]
    return b

plain_guesses = [
    '1','12','123','1234','12345','123456','admin','Admin','password','pass',
    'vietminh','vietminh123','uih','admin123','administrator','vgh2','abc','a'
]

results = []

# AES ECB/CBC with various key derivations
for keystr in keys:
    for kname, kfun in [
        ('md5-utf8', key_md5),
        ('md5-utf16le', key_md5_unicode),
        ('sha256[:16]', key_sha256_16),
        ('pad16-null', key_pad16),
        ('raw-repeat16', lambda s: key_repeat(s,16)),
        ('raw-repeat32', lambda s: key_repeat(s,32)),
    ]:
        try:
            key = kfun(keystr)
        except Exception:
            continue
        # AES ECB encrypt guesses
        if len(key) in (16,24,32):
            for mode_name, mode in [('ECB', AES.MODE_ECB), ('CBC-zeroIV', AES.MODE_CBC)]:
                for plain in plain_guesses:
                    try:
                        if mode == AES.MODE_ECB:
                            c = AES.new(key, mode)
                        else:
                            c = AES.new(key, mode, iv=b'\\x00'*16)
                        enc = c.encrypt(pad(plain.encode('utf-8'), 16))
                        if enc == ct or base64.b64encode(enc).decode() == ct_b64:
                            results.append(('AES', mode_name, kname, keystr, plain, 'ENCRYPT MATCH'))
                    except Exception as e:
                        pass
            # try decrypt
            try:
                if True:
                    c = AES.new(key, AES.MODE_ECB)
                    pt = unpad(c.decrypt(ct), 16)
                    results.append(('AES', 'ECB', kname, keystr, pt.decode('utf-8','replace'), 'DECRYPT OK'))
            except Exception:
                pass
            try:
                c = AES.new(key, AES.MODE_CBC, iv=b'\\x00'*16)
                pt = unpad(c.decrypt(ct), 16)
                results.append(('AES', 'CBC-zeroIV', kname, keystr, pt.decode('utf-8','replace'), 'DECRYPT OK'))
            except Exception:
                pass

# DES / 3DES
for keystr in keys:
    for kname, kfun, size in [
        ('md5[:8]', lambda s: key_md5(s)[:8], 8),
        ('pad8', lambda s: (s.encode()+b'\\0'*8)[:8], 8),
        ('md5', key_md5, 16),
        ('md5+4', lambda s: key_md5(s)+key_md5(s)[:8], 24),
    ]:
        try:
            key = kfun(keystr)
            if len(key)==8:
                for plain in plain_guesses:
                    try:
                        c = DES.new(key, DES.MODE_ECB)
                        enc = c.encrypt(pad(plain.encode('utf-8'), 8))
                        if enc == ct:
                            results.append(('DES','ECB',kname,keystr,plain,'ENCRYPT MATCH'))
                    except: pass
            if len(key) in (16,24):
                key3 = key[:24] if len(key)>=24 else key
                if len(key3)==16:
                    key3 = key3 + key3[:8]
                for plain in plain_guesses:
                    try:
                        c = DES3.new(key3, DES3.MODE_ECB)
                        enc = c.encrypt(pad(plain.encode('utf-8'), 8))
                        if enc == ct:
                            results.append(('3DES','ECB',kname,keystr,plain,'ENCRYPT MATCH'))
                    except: pass
        except Exception:
            pass

print('--- MATCHES ---')
for r in results:
    print(r)
print('total matches', len(results))
"

