/// <summary>
/// Kiểm tra định dạng tên đăng nhập theo chuẩn hệ thống.
/// vothihoailinh | VoThiHoaiLinh | TXSPK26K0615 | CDLT-KTML1712
/// </summary>
private bool IsValidLoginName(string loginName)
{
    if (loginName == null || loginName.Trim() == "")
        return false;

    string strName = loginName.Trim();

    // Chữ thường liền: vothihoailinh
    if (Regex.IsMatch(strName, @"^[a-z]+$"))
        return true;

    // PascalCase: VoThiHoaiLinh
    if (Regex.IsMatch(strName, @"^([A-Z][a-z]+)+$"))
        return true;

    // Mã in hoa + số: TXSPK26K0615
    if (Regex.IsMatch(strName, @"^[A-Z0-9]+$"))
        return true;

    // Mã có dấu gạch: CDLT-KTML1712
    if (Regex.IsMatch(strName, @"^[A-Z]+-[A-Z0-9]+$"))
        return true;

    return false;
}

private void ShowUserNameFormatError()
{
    lblUserNameError.Text = "Tên đăng nhập không đúng định dạng. Ví dụ: vothihoailinh, VoThiHoaiLinh, TXSPK26K0615, CDLT-KTML1712";
    lblUserNameError.Visible = true;
}

protected void btnLogin_Click(object sender, EventArgs e)
{
    lblUserNameError.Visible = false;
    lblUserNameError.Text = "";

    if (txtUserName.Text.Trim() == "" || txtPassword.Text == "")
        return;

    string strLoginName = txtUserName.Text.Trim();
    if (!IsValidLoginName(strLoginName))
    {
        ShowUserNameFormatError();
        return;
    }

    DoLogin(strLoginName, txtPassword.Text);
}

private void ShowUserNameFormatError()
{
    lblUserNameError.Text = "Tên đăng nhập không đúng định dạng quy định.";
    lblUserNameError.Visible = true;
}

